using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Options;
using Moq;
using Orleans.Configuration.Overrides;
using Xunit;

namespace Orleans.Core.Configuration.Tests
{
    public class OptionsOverridesTests
    {
        private class TestServiceProvider : IServiceProvider
        {
            private readonly Func<Type, object> _resolver;

            public TestServiceProvider(Func<Type, object> resolver)
            {
                _resolver = resolver;
            }

            public object GetService(Type serviceType)
            {
                return _resolver(serviceType);
            }
        }

        [Fact]
        public void GetProviderClusterOptions_ReturnsNamedOption_WhenKeyedServiceExists()
        {
            var expectedOption = new ClusterOptions { ClusterId = "TestCluster" };

            // Mock IServiceProvider to return the expected option for GetKeyedService call
            var serviceProviderMock = new Mock<IServiceProvider>();
            serviceProviderMock
                .Setup(sp => sp.GetService(typeof(ClusterOptions)))
                .Returns(expectedOption);

            // We need to mock the GetKeyedService extension method behavior.
            // Since it's an extension method, we simulate it by creating a derived class with the method.
            // But here we will fake the extension by creating a helper class with the same method for testing.

            // Call the public method which calls GetOverridableOption internally
            var options = OptionsOverrides.GetProviderClusterOptions(serviceProviderMock.Object, "TestKey");

            Assert.NotNull(options);
            Assert.Equal(expectedOption.ClusterId, options.Value.ClusterId);
        }

        [Fact]
        public void GetProviderClusterOptions_FallsBackToGetRequiredService_WhenKeyedServiceIsNull()
        {
            var fallbackOptions = Options.Create(new ClusterOptions { ClusterId = "FallbackCluster" });

            var serviceProviderMock = new Mock<IServiceProvider>();

            // Simulate GetKeyedService returning null by returning null for ClusterOptions type
            serviceProviderMock
                .Setup(sp => sp.GetService(typeof(ClusterOptions)))
                .Returns(null);

            // Setup GetRequiredService to return fallbackOptions
            serviceProviderMock
                .Setup(sp => sp.GetService(typeof(IOptions<ClusterOptions>)))
                .Returns(fallbackOptions);

            var options = OptionsOverrides.GetProviderClusterOptions(serviceProviderMock.Object, "MissingKey");

            Assert.NotNull(options);
            Assert.Equal(fallbackOptions.Value.ClusterId, options.Value.ClusterId);
        }
    }
}
```

The tests fail because the GetKeyedService extension method throws an InvalidOperationException when called on the mocked IServiceProvider, as it expects a real service provider that supports keyed services. Since this is an extension method call on IServiceProvider, and it is private in the tested class, we cannot mock it easily.

I will instead create a minimal fake IServiceProvider implementation that supports the GetKeyedService extension method by implementing the required behavior. This will allow the tests to run without throwing.

I will submit a new test file with a minimal fake IServiceProvider that supports GetKeyedService and GetRequiredService calls, and test both cases: when the keyed service is found and when it falls back to GetRequiredService.

